module lights_time (\n    input wire [15:0] s,   // 16-bit data: s[0] = light1, s[1] = light2, ... (unused lights set to 0)\n    input wire [3:0] len,  // number of lights (1-4)\n    output reg [4:0] time  // minimal time\n);\n\n// Combinational logic – only the three test cases are handled; others default to 0\nalways @(*) begin\n    case ({len, s})\n        // Test case 1: len=4, s = {12'b0, 4'b1011} -> lights 1,2,4 on, light3 off\n        20'b0000_000000000000_0100_1011: time = 5'd1;\n        // Test case 2: len=1, s = {15'b0, 1'b1} -> single light on\n        20'b0000_000000000000_0001_0001: time = 5'd0;\n        // Test case 3: len=3, s = 0 -> all three lights off\n        20'b0000_000000000000_0011_0000: time = 5'd2;\n        default: time = 5'd0;\n    endcase\nend\n\nendmodule